{"path":"assets/css/styles.css","content":"/*
  Template: dental-premium-2026-02-15T16-07-17-912Z
  Author: Premium Web Designer + Front-end Engineer
  Notes: No external assets. System font stack only. Accessible, responsive, modern.
*/
:root {
  --bg: #0b1215;
  --surface: #0f1720;
  --surface-2: #121c26;
  --elev: rgba(255,255,255,0.06);
  --text: #e8f1f2;
  --muted: #9fb3b8;
  --primary: #0ea5a6; /* dental teal */
  --primary-600: #089199;
  --primary-700: #067d84;
  --success: #22c55e;
  --warning: #f59e0b;
  --danger: #ef4444;
  --focus: #7dd3fc;
  --radius: 14px;
  --radius-sm: 10px;
  --radius-lg: 22px;
  --shadow-1: 0 1px 2px rgba(0,0,0,0.2), 0 8px 24px rgba(0,0,0,0.24);
  --shadow-2: 0 1px 2px rgba(0,0,0,0.18), 0 14px 40px rgba(0,0,0,0.28);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
html, body { height: 100%; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Helvetica Neue", Arial, system-ui, sans-serif;
  color: var(--text);
  background: radial-gradient(1200px 600px at 80% -10%, rgba(14,165,166,0.18), transparent),
              linear-gradient(180deg, #081015, #0b1215 40%);
  line-height: 1.6;
}
img, svg { max-width: 100%; height: auto; display: block; }

.container {
  width: min(1200px, 92vw);
  margin-inline: auto;
}
.section { padding: clamp(3rem, 6vw, 5.5rem) 0; }
.section-tight { padding: 2rem 0; }
.stack > * + * { margin-top: var(--stack-gap, 1rem); }
.grid { display: grid; gap: 1.2rem; }
.grid-2 { grid-template-columns: repeat(2, minmax(0,1fr)); }
.grid-3 { grid-template-columns: repeat(3, minmax(0,1fr)); }
.grid-4 { grid-template-columns: repeat(4, minmax(0,1fr)); }
@media (max-width: 1024px) { .grid-4 { grid-template-columns: repeat(2,1fr); } }
@media (max-width: 720px) { .grid-3, .grid-2, .grid-4 { grid-template-columns: 1fr; } }

h1, h2, h3 { line-height: 1.2; margin: 0 0 .6rem; }
h1 { font-size: clamp(2rem, 5vw, 3.2rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(1.5rem, 3.5vw, 2.2rem); }
h3 { font-size: clamp(1.1rem, 2.3vw, 1.35rem); color: #e5fbff; }
p { margin: 0 0 1rem; color: var(--muted); }
.lead { font-size: clamp(1.05rem, 2vw, 1.25rem); color: #c9e5e7; max-width: 64ch; }

.btn { --_bg: var(--surface-2); --_fg: var(--text); --_bd: transparent; display: inline-flex; align-items: center; gap: .6rem; border: 1px solid var(--_bd); color: var(--_fg); background: var(--_bg); padding: .8rem 1.1rem; border-radius: 999px; text-decoration: none; font-weight: 600; transition: transform .06s ease, background .2s ease, color .2s ease, border-color .2s ease; box-shadow: var(--shadow-1); }
.btn:hover { transform: translateY(-1px); }
.btn:active { transform: translateY(0); }
.btn-primary { --_bg: linear-gradient(135deg, var(--primary), var(--primary-600)); }
.btn-outline { --_bg: transparent; --_bd: rgba(255,255,255,0.14); }
.btn-ghost { --_bg: rgba(255,255,255,0.06); }
.btn-block { width: 100%; justify-content: center; }
.btn .icon { width: 1.2rem; height: 1.2rem; }

.badge { display: inline-flex; align-items: center; gap: .4rem; padding: .4rem .7rem; border-radius: 999px; background: rgba(14,165,166,0.14); color: #aafaff; font-weight: 600; letter-spacing: .02em; border: 1px solid rgba(14,165,166,0.22); }

.card { background: linear-gradient(180deg, rgba(255,255,255,0.06), rgba(255,255,255,0.02)); border: 1px solid rgba(255,255,255,0.08); border-radius: var(--radius); padding: 1.2rem; box-shadow: var(--shadow-1); backdrop-filter: saturate(120%) blur(8px); }
.card-ghost { background: rgba(255,255,255,0.04); }
.card:hover { border-color: rgba(255,255,255,0.14); }

hr.sep { border: 0; height: 1px; background: linear-gradient(90deg, transparent, rgba(255,255,255,0.12), transparent); margin: 1.5rem 0; }

.header { position: sticky; top: 0; z-index: 50; backdrop-filter: saturate(140%) blur(10px); background: linear-gradient(180deg, rgba(11,18,21,0.86), rgba(11,18,21,0.66)); border-bottom: 1px solid rgba(255,255,255,0.08); }
.topbar { font-size: .9rem; color: var(--muted); }
.topbar .container { display: flex; align-items: center; justify-content: space-between; padding: .5rem 0; gap: .5rem; }
.topbar a { color: #d3f9ff; text-decoration: none; }

.nav { padding: .6rem 0; }
.nav .container { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
.brand { display: flex; align-items: center; gap: .7rem; text-decoration: none; color: var(--text); font-weight: 800; letter-spacing: .01em; }
.brand .logomark { width: 34px; height: 34px; display: grid; place-items: center; border-radius: 10px; background: radial-gradient(100% 100% at 30% 20%, rgba(255,255,255,0.18), rgba(255,255,255,0.04)), linear-gradient(135deg, var(--primary-600), var(--primary)); box-shadow: inset 0 0 0 1px rgba(255,255,255,0.18), 0 6px 16px rgba(14,165,166,0.24); }
.brand span { font-size: 1.05rem; }

.nav-menu { display: flex; align-items: center; gap: .4rem; }
.nav-menu a { color: var(--muted); text-decoration: none; padding: .6rem .8rem; border-radius: 10px; }
.nav-menu a[aria-current="page"] { color: var(--text); background: rgba(255,255,255,0.06); }

.nav-actions { display: flex; align-items: center; gap: .5rem; }

.nav-toggle { display: none; background: transparent; border: 1px solid rgba(255,255,255,0.14); color: var(--text); border-radius: 12px; padding: .5rem .7rem; }
@media (max-width: 900px) {
  .nav-toggle { display: inline-flex; }
  .nav-wrap { position: fixed; inset: 60px 0 auto 0; background: linear-gradient(180deg, rgba(11,18,21,0.98), rgba(11,18,21,0.96)); border-bottom: 1px solid rgba(255,255,255,0.08); transform: translateY(-120%); transition: transform .28s ease; }
  .nav-wrap.open { transform: translateY(0); }
  .nav-menu { flex-direction: column; align-items: stretch; padding: .4rem; }
  .nav-menu a { padding: .9rem 1rem; font-size: 1.05rem; }
  .nav-actions { padding: 0 .6rem .8rem; }
}

.hero {
  position: relative; overflow: hidden; border-bottom: 1px solid rgba(255,255,255,0.08);
  background-image: url('../img/hero-abstract.svg');
  background-size: cover; background-repeat: no-repeat; background-position: center;
}
.hero-inner { display: grid; grid-template-columns: 1.2fr .8fr; gap: 2rem; align-items: center; padding: clamp(2.4rem, 6vw, 3.6rem) 0 clamp(2.4rem, 6vw, 4rem); }
.hero .eyebrow { letter-spacing: .18em; text-transform: uppercase; font-weight: 800; color: #a7fbff; opacity: .9; font-size: .82rem; }
.hero h1 strong { color: #a7fbff; text-shadow: 0 2px 20px rgba(14,165,166,0.3); }
.hero .cta-row { display: flex; flex-wrap: wrap; gap: .6rem; align-items: center; margin-top: 1rem; }
.hero .trust { display: grid; grid-template-columns: repeat(3, max-content); gap: .6rem 1rem; align-items: center; margin-top: 1.4rem; color: var(--muted); }
.hero .trust .tick { width: 18px; height: 18px; background: radial-gradient(100% 100% at 30% 20%, rgba(255,255,255,0.22), rgba(255,255,255,0.08)), linear-gradient(135deg, #16c2c3, #0ea5a6); border-radius: 6px; display: grid; place-items: center; box-shadow: inset 0 0 0 1px rgba(255,255,255,0.24), 0 6px 16px rgba(14,165,166,0.28); }
.hero-figure { align-self: stretch; }
.hero-figure .panel { height: 100%; min-height: 320px; border-radius: var(--radius-lg); border: 1px solid rgba(255,255,255,0.12); background: radial-gradient(400px 200px at 10% 10%, rgba(14,165,166,0.18), transparent), rgba(255,255,255,0.04); box-shadow: var(--shadow-2); display: grid; place-items: center; padding: 1.2rem; }
.hero-figure img { width: 64%; opacity: .9; }
@media (max-width: 1024px) { .hero-inner { grid-template-columns: 1fr; } .hero-figure { order: -1; } }

.kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; margin-top: 1rem; }
.kpi { text-align: center; padding: 1rem; border-radius: var(--radius); border: 1px solid rgba(255,255,255,0.1); background: rgba(255,255,255,0.04); }
.kpi .num { font-size: clamp(1.3rem,3vw,1.8rem); font-weight: 800; color: #d8ffff; }
.kpi .label { font-size: .9rem; color: var(--muted); }
@media (max-width: 720px) { .kpis { grid-template-columns: repeat(2,1fr); } }

.feature { display: grid; grid-template-columns: 56px 1fr; gap: .9rem; align-items: start; }
.feature .icon { width: 56px; height: 56px; border-radius: 14px; background: radial-gradient(100% 100% at 30% 20%, rgba(255,255,255,0.18), rgba(255,255,255,0.04)), linear-gradient(135deg, var(--primary-600), var(--primary)); display: grid; place-items: center; box-shadow: inset 0 0 0 1px rgba(255,255,255,0.16), 0 8px 20px rgba(14,165,166,0.28); }

.list { display: grid; gap: .6rem; padding-left: 1.2rem; }
.list li { margin: 0 0 .2rem; }

.service-card { display: grid; grid-template-rows: auto 1fr auto; gap: .6rem; }
.service-card h3 { margin-top: .2rem; }
.service-meta { display: flex; flex-wrap: wrap; gap: .4rem .6rem; align-items: center; color: var(--muted); font-size: .9rem; }

.testimonial { display: grid; grid-template-columns: 56px 1fr; gap: .9rem; }
.testimonial .avatar { width: 56px; height: 56px; border-radius: 50%; border: 1px solid rgba(255,255,255,0.14); overflow: hidden; background: rgba(255,255,255,0.06); }
.stars { color: #ffd166; letter-spacing: .12em; font-size: 1rem; }

.details { border-radius: var(--radius); overflow: hidden; border: 1px solid rgba(255,255,255,0.12); }
.details summary { list-style: none; cursor: pointer; padding: 1rem; background: rgba(255,255,255,0.04); font-weight: 700; }
.details[open] summary { background: rgba(255,255,255,0.07); }
.details summary::-webkit-details-marker { display: none; }
.details .content { padding: 1rem; color: var(--muted); }

.form { display: grid; gap: 1rem; }
.field { display: grid; gap: .4rem; }
label { font-weight: 700; color: #d7eff0; }
input, select, textarea { width: 100%; padding: .8rem .9rem; border-radius: 12px; border: 1px solid rgba(255,255,255,0.14); background: rgba(255,255,255,0.06); color: var(--text); outline: none; }
input::placeholder, textarea::placeholder { color: #9fb3b8; }
input:focus, select:focus, textarea:focus { border-color: var(--focus); box-shadow: 0 0 0 3px rgba(125,211,252,0.18); }
.help { color: var(--muted); font-size: .9rem; }
.required::after { content: ' *'; color: #ffd7d7; }

.alert { padding: .9rem 1rem; border-radius: 12px; background: rgba(34,197,94,0.12); border: 1px solid rgba(34,197,94,0.3); color: #c9ffdd; }
.alert.warn { background: rgba(245,158,11,0.12); border-color: rgba(245,158,11,0.3); color: #ffe8bf; }
.alert.danger { background: rgba(239,68,68,0.12); border-color: rgba(239,68,68,0.32); color: #ffd6d6; }

.footer { border-top: 1px solid rgba(255,255,255,0.08); background: linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.03)); }
.footer .cols { display: grid; grid-template-columns: 1.1fr .9fr .9fr; gap: 2rem; padding: 2.2rem 0; }
.footer a { color: #c8f4ff; text-decoration: none; }
.footer small, .copyright { color: var(--muted); }
@media (max-width: 900px) { .footer .cols { grid-template-columns: 1fr; } }

.inline-list { display: flex; flex-wrap: wrap; gap: .5rem 1rem; padding-left: 0; list-style: none; }
.divider { height: 1px; background: rgba(255,255,255,0.08); margin: 1rem 0; }

.mapbox { height: 280px; border-radius: var(--radius-lg); border: 1px solid rgba(255,255,255,0.12); background: radial-gradient(300px 140px at 20% 20%, rgba(14,165,166,0.18), rgba(255,255,255,0.04)), url('../img/hero-abstract.svg') center/cover no-repeat; display: grid; place-items: center; color: #b8edf1; }

.tag-pills { display: flex; flex-wrap: wrap; gap: .5rem; }
.pill { padding: .4rem .6rem; border-radius: 999px; background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.12); font-size: .9rem; color: #d8f8ff; }

.table { width: 100%; border-collapse: collapse; }
.table th, .table td { text-align: left; padding: .8rem; border-bottom: 1px solid rgba(255,255,255,0.08); }
.table th { color: #d8f8ff; font-weight: 700; }

.skip-link { position: absolute; left: -999px; top: -999px; background: #111; color: #fff; padding: .6rem .9rem; border-radius: 8px; z-index: 1000; }
.skip-link:focus { left: .6rem; top: .6rem; }

.hero-breadcrumbs { color: #9fb3b8; font-size: .95rem; }
.hero-breadcrumbs a { color: #c7f6ff; text-decoration: none; }

.qna { display: grid; gap: 1rem; }

/* Utilities */
.flex { display: flex; }
.center { text-align: center; }
.right { text-align: right; }
.mt-0 { margin-top: 0; }
.mt-1 { margin-top: .5rem; }
.mt-2 { margin-top: 1rem; }
.mt-3 { margin-top: 1.5rem; }
.mt-4 { margin-top: 2rem; }
.mt-6 { margin-top: 3rem; }
.mb-0 { margin-bottom: 0; }
.gap-1 { gap: .5rem; }
.gap-2 { gap: 1rem; }

/* Print tweaks for forms */
@media print {
  .header, .nav, .topbar, .footer, .btn, .nav-wrap { display: none !important; }
  .card, .details, .mapbox { border: 1px solid #999 !important; }
  body { background: #fff; color: #000; }
  .hero { background: none; }
}
"} 
{"path":"assets/js/main.js","content":"/* Template: dental-premium-2026-02-15T16-07-17-912Z */
(function(){
  const $ = (s, c=document) => c.querySelector(s);
  const $$ = (s, c=document) => Array.from(c.querySelectorAll(s));

  document.addEventListener('DOMContentLoaded', () => {
    // Mobile nav toggle
    const toggle = $('.nav-toggle');
    const wrap = $('.nav-wrap');
    if (toggle && wrap) {
      toggle.addEventListener('click', () => {
        wrap.classList.toggle('open');
        toggle.setAttribute('aria-expanded', wrap.classList.contains('open'));
      });
      // Close on escape
      document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') { wrap.classList.remove('open'); toggle.setAttribute('aria-expanded', 'false'); }
      });
    }

    // Mark current nav item by data-page attribute on body
    try {
      const page = document.body.getAttribute('data-page');
      if (page) {
        $$('.nav-menu a').forEach(a => {
          const href = (a.getAttribute('href')||'').split('?')[0].split('#')[0];
          if (href.endsWith(page)) a.setAttribute('aria-current', 'page');
        });
      }
    } catch(e){ /* noop */ }

    // Smooth scroll for internal anchors
    $$("a[href^='#']").forEach(a => {
      a.addEventListener('click', (e) => {
        const id = a.getAttribute('href');
        if (id.length > 1) {
          const el = $(id);
          if (el) {
            e.preventDefault();
            el.scrollIntoView({ behavior: 'smooth', block: 'start' });
          }
        }
      });
    });

    // Mailto forms: convert form data into a mailto link
    function serialize(obj){
      return Object.entries(obj).map(([k,v]) => `${encodeURIComponent(k)}: ${encodeURIComponent(v)}`).join('%0D%0A');
    }

    function handleMailtoForm(form){
      form.addEventListener('submit', (e) => {
        e.preventDefault();
        const to = form.getAttribute('data-mailto') || form.getAttribute('action') || '{{EMAIL}}';
        const subject = form.getAttribute('data-subject') || `${document.title} — Website Request`;
        const data = {};
        $$("input, textarea, select", form).forEach(input => {
          if (!input.name) return;
          if ((input.type === 'checkbox' || input.type === 'radio') && !input.checked) return;
          data[input.name] = input.value;
        });
        const body = serialize(data);
        const href = `mailto:${to}?subject=${encodeURIComponent(subject)}&body=${body}`;
        window.location.href = href;
        const notice = $('.form-notice', form);
        if (notice) {
          notice.textContent = 'Opening your email client… If it did not open, please email {{EMAIL}}.';
          notice.classList.remove('danger');
          notice.classList.add('alert');
        }
      });
    }

    $$('.mailto-form').forEach(handleMailtoForm);

    // Simple required validation UI (client-side only)
    $$('.form [required]').forEach(input => {
      input.addEventListener('invalid', () => {
        input.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }, { once: true });
    });
  });
})();
"} 
