{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{{BUSINESS_NAME}} | {{TAGLINE}}</title>
  <meta name="description" content="{{BUSINESS_NAME}} provides modern, gentle dental care in {{CITY}}, {{STATE}}. Comprehensive family dentistry, cosmetic smile design, dental implants, emergencies, and more.">
  <meta name="theme-color" content="#0ea5a6">
  <link rel="preload" as="image" href="assets/img/hero-abstract.svg">
  <meta property="og:title" content="{{BUSINESS_NAME}} — {{TAGLINE}}">
  <meta property="og:description" content="Modern, gentle dental care in {{CITY}}, {{STATE}}. Family, cosmetic, and implant dentistry with comfort-first technology.">
  <meta property="og:type" content="website">
  <meta property="og:url" content="index.html">
  <meta property="og:image" content="assets/img/hero-abstract.svg">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:title" content="{{BUSINESS_NAME}} — {{TAGLINE}}">
  <meta name="twitter:description" content="Modern, gentle dental care in {{CITY}}, {{STATE}}. Family, cosmetic, and implant dentistry.">
  <link rel="canonical" href="index.html">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
  <script type="application/ld+json">{
    "@context":"https://schema.org",
    "@type":"Dentist",
    "name":"{{BUSINESS_NAME}}",
    "description":"{{TAGLINE}}",
    "telephone":"{{PHONE}}",
    "email":"{{EMAIL}}",
    "url":"index.html",
    "address":{
      "@type":"PostalAddress",
      "streetAddress":"{{ADDRESS}}",
      "addressLocality":"{{CITY}}",
      "addressRegion":"{{STATE}}",
      "postalCode":"{{ZIP}}"
    },
    "openingHours":"{{HOURS}}"
  }</script>
</head>
<body data-page="index.html">
  <a href="#main" class="skip-link">Skip to content</a>
  <header class="header" role="banner">
    <div class="topbar">
      <div class="container">
        <div><strong>{{CITY}}, {{STATE}}</strong> • {{ADDRESS}}</div>
        <div class="inline-list">
          <a href="tel:{{PHONE}}" aria-label="Call us">Call {{PHONE}}</a>
          <span aria-hidden="true">•</span>
          <a href="mailto:{{EMAIL}}" aria-label="Email us">Email {{EMAIL}}</a>
          <span aria-hidden="true">•</span>
          <span>Hours: {{HOURS}}</span>
        </div>
      </div>
    </div>
    <nav class="nav" aria-label="Primary">
      <div class="container">
        <a class="brand" href="index.html">
          <span class="logomark" aria-hidden="true">
